window.__code__["code-w03-plan-execute-py"] = {"code_id": "code-w03-plan-execute-py", "kind": "local", "title": "plan_execute.py", "source_path": "/Users/zhongyou/Desktop/2027年/code/w03/plan_execute.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># code/w03/plan_execute.py</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-com\"># W03 作业2:手写 Plan-and-Execute(不依赖框架)</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-com\"># 与 ReAct 区别:先让模型一次性出 JSON 计划,再逐步执行;支持 replan</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-com\"># 前置: export DASHSCOPE_API_KEY=\u00004\u0000</span></span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-com\"># 运行:  python code/w03/plan_execute.py</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-com\"># 预期:  模型先输出计划(JSON),逐步执行工具,最后汇总答案</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-kw\">import</span> json</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">from</span> openai <span class=\"c-kw\">import</span> OpenAI</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">client = OpenAI(</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">    api_key=os.environ[<span class=\"c-str\">&quot;DASHSCOPE_API_KEY&quot;</span>],</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">    base_url=<span class=\"c-str\">&quot;https://dashscope.aliyuncs.com/compatible-mode/v1&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\"><span class=\"c-kw\">def</span> get_weather(city: str) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> {<span class=\"c-str\">&quot;杭州&quot;</span>: <span class=\"c-str\">&quot;28度晴&quot;</span>, <span class=\"c-str\">&quot;北京&quot;</span>: <span class=\"c-str\">&quot;30度多云&quot;</span>}.get(city, <span class=\"c-str\">&quot;未知&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\"><span class=\"c-kw\">def</span> calc(expression: str) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> str(eval(expression, {<span class=\"c-str\">&quot;__builtins__&quot;</span>: {}}, {}))</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">    <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> f<span class=\"c-str\">&quot;计算错误: {e}&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">NAME2FN = {<span class=\"c-str\">&quot;get_weather&quot;</span>: get_weather, <span class=\"c-str\">&quot;calc&quot;</span>: calc}</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">PLANNER_SYS = <span class=\"c-str\">&quot;&quot;</span>&quot;你是任务规划器。把用户任务拆成 JSON 步骤数组,严格只输出 JSON。</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">每步格式: {<span class=\"c-str\">&quot;step&quot;</span>: 整数, <span class=\"c-str\">&quot;tool&quot;</span>: <span class=\"c-str\">&quot;get_weather&quot;</span>|<span class=\"c-str\">&quot;calc&quot;</span>|<span class=\"c-str\">&quot;done&quot;</span>, <span class=\"c-str\">&quot;args&quot;</span>: {...}, <span class=\"c-str\">&quot;desc&quot;</span>: <span class=\"c-str\">&quot;说明&quot;</span>}</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">- get_weather 的 args: {<span class=\"c-str\">&quot;city&quot;</span>: <span class=\"c-str\">&quot;...&quot;</span>}</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">- calc 的 args: {<span class=\"c-str\">&quot;expression&quot;</span>: <span class=\"c-str\">&quot;如 28*3 的字符串&quot;</span>}</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">- done 表示所有步骤完成,给出最终答案放进 args: {<span class=\"c-str\">&quot;answer&quot;</span>: <span class=\"c-str\">&quot;...&quot;</span>}</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">示例输出:</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">[{<span class=\"c-str\">&quot;step&quot;</span>:1,<span class=\"c-str\">&quot;tool&quot;</span>:<span class=\"c-str\">&quot;get_weather&quot;</span>,<span class=\"c-str\">&quot;args&quot;</span>:{<span class=\"c-str\">&quot;city&quot;</span>:<span class=\"c-str\">&quot;杭州&quot;</span>},<span class=\"c-str\">&quot;desc&quot;</span>:<span class=\"c-str\">&quot;查杭州天气&quot;</span>},</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\"> {<span class=\"c-str\">&quot;step&quot;</span>:2,<span class=\"c-str\">&quot;tool&quot;</span>:<span class=\"c-str\">&quot;done&quot;</span>,<span class=\"c-str\">&quot;args&quot;</span>:{<span class=\"c-str\">&quot;answer&quot;</span>:<span class=\"c-str\">&quot;根据天气回答&quot;</span>},<span class=\"c-str\">&quot;desc&quot;</span>:<span class=\"c-str\">&quot;汇总&quot;</span>}]<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\"><span class=\"c-kw\">def</span> plan_execute(user_query: str) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">    <span class=\"c-com\"># ===== 步骤1: 规划(模型出 JSON 计划) =====</span></span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">    resp = client.chat.completions.create(</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">        model=<span class=\"c-str\">&quot;qwen-plus&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">        messages=[</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">            {<span class=\"c-str\">&quot;role&quot;</span>: <span class=\"c-str\">&quot;system&quot;</span>, <span class=\"c-str\">&quot;content&quot;</span>: PLANNER_SYS},</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">            {<span class=\"c-str\">&quot;role&quot;</span>: <span class=\"c-str\">&quot;user&quot;</span>, <span class=\"c-str\">&quot;content&quot;</span>: user_query},</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">        ],</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">        response_format={<span class=\"c-str\">&quot;type&quot;</span>: <span class=\"c-str\">&quot;json_object&quot;</span>},  <span class=\"c-com\"># 强制 JSON 输出</span></span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">    raw = resp.choices[0].message.content</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">    <span class=\"c-com\"># 模型可能返回 {\u000063\u0000: [...]} 或直接 [...]，做兼容</span></span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">    parsed = json.loads(raw)</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">    plan = parsed[<span class=\"c-str\">&quot;plan&quot;</span>] <span class=\"c-kw\">if</span> isinstance(parsed, dict) <span class=\"c-kw\">and</span> <span class=\"c-str\">&quot;plan&quot;</span> <span class=\"c-kw\">in</span> parsed <span class=\"c-kw\">else</span> parsed</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">    print(f<span class=\"c-str\">&quot;📋 计划:&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">    <span class=\"c-kw\">for</span> step <span class=\"c-kw\">in</span> plan:</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">        print(f<span class=\"c-str\">&quot;   {step}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">    <span class=\"c-com\"># ===== 步骤2: 逐步执行(可触发 replan) =====</span></span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">    results: dict[int, str] = {}</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">    <span class=\"c-kw\">for</span> step <span class=\"c-kw\">in</span> plan:</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">        tool = step[<span class=\"c-str\">&quot;tool&quot;</span>]</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">        args = step.get(<span class=\"c-str\">&quot;args&quot;</span>, {})</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> tool == <span class=\"c-str\">&quot;done&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">            <span class=\"c-com\"># 汇总阶段:可把已收集结果回灌模型做最终总结(replan 也在这做)</span></span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">            summary_prompt = (</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;用户问题:{user_query}\\n已收集信息:{results}\\n&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;模型原计划答案:{args.get(&#x27;answer&#x27;,&#x27;&#x27;)}\\n请据此给最终自然语言答案。&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">            final = client.chat.completions.create(</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">                model=<span class=\"c-str\">&quot;qwen-plus&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">                messages=[{<span class=\"c-str\">&quot;role&quot;</span>: <span class=\"c-str\">&quot;user&quot;</span>, <span class=\"c-str\">&quot;content&quot;</span>: summary_prompt}],</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> final.choices[0].message.content</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">        <span class=\"c-com\"># 执行真实工具</span></span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">        result = NAME2FN[tool](**args)</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">        print(f<span class=\"c-str\">&quot;   ▶ 执行 step{step[&#x27;step&#x27;]} {tool}({args}) -&gt; {result}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">        results[step[<span class=\"c-str\">&quot;step&quot;</span>]] = result</span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">        <span class=\"c-com\"># 进阶 replan:把结果回灌,问模型\u000083\u0000</span></span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">        <span class=\"c-com\"># (此处简化跳过;真实 Plan-Execute 在发现某步无意义时会重新调规划器)</span></span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> <span class=\"c-str\">&quot;(计划执行完但未见 done 步骤)&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\"><span class=\"c-kw\">if</span> __name__ == <span class=\"c-str\">&quot;__main__&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">    print(plan_execute(<span class=\"c-str\">&quot;杭州天气温度乘以3是多少?&quot;</span>))</span></div>\n</div>", "lines": 89, "explanation": "plan_execute.py 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [], "related_docs": ["W03-手写ReAct与Plan-Execute循环"]};
